const os = require("os");
const config = require("./config");

// generated by Gemini AI
class Metrics {
  constructor() {
    // 1. HTTP requests
    this.totalRequests = 0;
    this.methodRequests = { GET: 0, POST: 0, PUT: 0, DELETE: 0 };

    // 2. Latency
    this.endpointLatencies = {}; // { "[GET] /api/order": lastLatencyMs }

    // 3. Active Users
    this.activeUsers = new Set();

    // 4. Auth attempts
    this.authSuccesses = 0;
    this.authFailures = 0;

    // 5. Pizza metrics
    this.pizzasSold = 0;
    this.pizzaFailures = 0;
    this.pizzaRevenue = 0;
    this.pizzaCreationLatency = 0;

    // Periodically send metrics every 10 seconds (don't block test suites)
    if (process.env.NODE_ENV !== "test") {
      this.sendInterval = setInterval(() => {
        try {
          const metrics = this.buildMetrics();
          this.sendMetricToGrafana(metrics);
        } catch (err) {
          console.error("Error reporting metrics:", err);
        }
      }, 10000);
    }
  }

  // --- Express Middleware for HTTP counts & Endpoint Latency ---
  requestTracker = (req, res, next) => {
    const startTime = Date.now();
    this.totalRequests++;

    const method = req.method.toUpperCase();
    if (this.methodRequests[method] !== undefined) {
      this.methodRequests[method]++;
    }

    res.on("finish", () => {
      const latency = Date.now() - startTime;
      const endpoint = `[${req.method}] ${req.baseUrl || ""}${req.path || ""}`;
      this.endpointLatencies[endpoint] = latency;
    });

    next();
  };

  // --- Trackers called from routes ---
  trackAuth(success) {
    if (success) {
      this.authSuccesses++;
    } else {
      this.authFailures++;
    }
  }

  trackUserLogin(userId) {
    if (userId) this.activeUsers.add(userId);
  }

  trackUserLogout(userId) {
    if (userId) this.activeUsers.delete(userId);
  }

  trackPizzaPurchase(success, count, revenue, factoryLatency) {
    if (success) {
      this.pizzasSold += count;
      this.pizzaRevenue += revenue;
      this.pizzaCreationLatency = factoryLatency;
    } else {
      this.pizzaFailures++;
    }
  }

  // --- System Resource Calculations ---
  getCpuUsagePercentage() {
    const cpuUsage = os.loadavg()[0] / os.cpus().length;
    return parseFloat((cpuUsage * 100).toFixed(2));
  }

  getMemoryUsagePercentage() {
    const totalMemory = os.totalmem();
    const freeMemory = os.freemem();
    const usedMemory = totalMemory - freeMemory;
    return parseFloat(((usedMemory / totalMemory) * 100).toFixed(2));
  }

  // --- Build OTLP Metrics Array ---
  buildMetrics() {
    const metrics = [];

    // 1. HTTP counts
    metrics.push(
      this.createMetric(
        "request_total",
        this.totalRequests,
        "1",
        "sum",
        "asInt",
        {},
      ),
    );
    for (const [method, count] of Object.entries(this.methodRequests)) {
      metrics.push(
        this.createMetric("request_method", count, "1", "sum", "asInt", {
          method: method.toLowerCase(),
        }),
      );
    }

    // 2. Active users
    metrics.push(
      this.createMetric(
        "active_users",
        this.activeUsers.size,
        "1",
        "gauge",
        "asInt",
        {},
      ),
    );

    // 3. Auth attempts
    metrics.push(
      this.createMetric(
        "auth_attempts",
        this.authSuccesses,
        "1",
        "sum",
        "asInt",
        { status: "success" },
      ),
    );
    metrics.push(
      this.createMetric(
        "auth_attempts",
        this.authFailures,
        "1",
        "sum",
        "asInt",
        { status: "failure" },
      ),
    );

    // 4. System Usage
    metrics.push(
      this.createMetric(
        "cpu_usage",
        this.getCpuUsagePercentage(),
        "%",
        "gauge",
        "asDouble",
        {},
      ),
    );
    metrics.push(
      this.createMetric(
        "memory_usage",
        this.getMemoryUsagePercentage(),
        "%",
        "gauge",
        "asDouble",
        {},
      ),
    );

    // 5. Pizza & Revenue
    metrics.push(
      this.createMetric(
        "pizzas_sold",
        this.pizzasSold,
        "1",
        "sum",
        "asInt",
        {},
      ),
    );
    metrics.push(
      this.createMetric(
        "pizza_failures",
        this.pizzaFailures,
        "1",
        "sum",
        "asInt",
        {},
      ),
    );
    metrics.push(
      this.createMetric(
        "pizza_revenue",
        parseFloat(this.pizzaRevenue.toFixed(4)),
        "BTC",
        "sum",
        "asDouble",
        {},
      ),
    );

    // 6. Latency
    metrics.push(
      this.createMetric(
        "pizza_creation_latency",
        this.pizzaCreationLatency,
        "ms",
        "gauge",
        "asInt",
        {},
      ),
    );
    for (const [endpoint, latency] of Object.entries(this.endpointLatencies)) {
      metrics.push(
        this.createMetric("service_latency", latency, "ms", "gauge", "asInt", {
          endpoint,
        }),
      );
    }

    return metrics;
  }

  createMetric(
    metricName,
    metricValue,
    metricUnit,
    metricType,
    valueType,
    attributes,
  ) {
    const source =
      (config.metrics && config.metrics.source) ||
      config.source ||
      "jwt-pizza-service";
    attributes = { ...attributes, source };

    const metric = {
      name: metricName,
      unit: metricUnit,
      [metricType]: {
        dataPoints: [
          {
            [valueType]: metricValue,
            timeUnixNano: Date.now() * 1000000,
            attributes: [],
          },
        ],
      },
    };

    Object.keys(attributes).forEach((key) => {
      metric[metricType].dataPoints[0].attributes.push({
        key: key,
        value: { stringValue: String(attributes[key]) },
      });
    });

    if (metricType === "sum") {
      metric[metricType].aggregationTemporality =
        "AGGREGATION_TEMPORALITY_CUMULATIVE";
      metric[metricType].isMonotonic = true;
    }

    return metric;
  }

  sendMetricToGrafana(metrics) {
    const metricsConfig = config.metrics || config;
    const url = metricsConfig.url || metricsConfig.endpointUrl;
    const userId = metricsConfig.userId || metricsConfig.accountId;
    const apiKey = metricsConfig.apiKey;

    if (!url || !apiKey) return;

    const body = {
      resourceMetrics: [
        {
          scopeMetrics: [{ metrics }],
        },
      ],
    };

    fetch(url, {
      method: "POST",
      body: JSON.stringify(body),
      headers: {
        Authorization: `Bearer ${userId}:${apiKey}`,
        "Content-Type": "application/json",
      },
    }).catch((err) => {
      console.error("Error pushing metrics:", err.message);
    });
  }
}

const metrics = new Metrics();
module.exports = metrics;
